import { randomUUID } from "node:crypto";
import { readFile, writeFile, mkdir } from "node:fs/promises";
import path from "node:path";

const EMPTY = { books: [] };

export function createStore(filePath) {
  let writing = Promise.resolve();

  async function ensureFile() {
    await mkdir(path.dirname(filePath), { recursive: true });
    try {
      await readFile(filePath, "utf8");
    } catch (err) {
      if (err.code !== "ENOENT") throw err;
      await writeFile(filePath, JSON.stringify(EMPTY, null, 2));
    }
  }

  async function read() {
    await ensureFile();
    const raw = await readFile(filePath, "utf8");
    const data = raw.trim() ? JSON.parse(raw) : EMPTY;
    if (!data || !Array.isArray(data.books)) return { books: [] };
    return data;
  }

  function write(data) {
    writing = writing.then(() =>
      writeFile(filePath, JSON.stringify(data, null, 2))
    );
    return writing;
  }

  return {
    async list() {
      const data = await read();
      return data.books;
    },

    async get(id) {
      const books = await this.list();
      return books.find((book) => book.id === id) ?? null;
    },

    async add({ title, author, notes }) {
      const book = {
        id: randomUUID(),
        title: title.trim(),
        author: author.trim(),
        notes: (notes ?? "").trim(),
        status: "reading",
        createdAt: new Date().toISOString(),
      };
      const data = await read();
      data.books.unshift(book);
      await write(data);
      return book;
    },

    async finish(id) {
      const data = await read();
      const book = data.books.find((item) => item.id === id);
      if (!book) return null;
      if (book.status !== "finished") {
        book.status = "finished";
        book.finishedAt = new Date().toISOString();
        await write(data);
      }
      return book;
    },
  };
}

