export function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function layout(title, body) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)}</title>
  <style>
    :root { color-scheme: light; }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      font: 16px/1.45 system-ui, sans-serif;
      background: #f6f3ee;
      color: #1c1917;
    }
    main { max-width: 40rem; margin: 0 auto; padding: 2rem 1.25rem 4rem; }
    h1 { font-size: 1.75rem; margin: 0 0 0.25rem; }
    h2 { font-size: 1.05rem; margin: 2rem 0 0.75rem; }
    a { color: #9a3412; }
    .lede { margin: 0 0 1.5rem; color: #57534e; }
    form, article, li {
      background: #fff;
      border: 1px solid #e7e5e4;
      border-radius: 8px;
    }
    form { padding: 1rem; display: grid; gap: 0.75rem; }
    label { display: grid; gap: 0.25rem; font-size: 0.9rem; }
    input, textarea {
      font: inherit;
      padding: 0.45rem 0.55rem;
      border: 1px solid #d6d3d1;
      border-radius: 6px;
    }
    textarea { min-height: 5rem; resize: vertical; }
    button, .button {
      font: inherit;
      background: #9a3412;
      color: #fff;
      border: 0;
      border-radius: 6px;
      padding: 0.5rem 0.8rem;
      cursor: pointer;
      text-decoration: none;
      display: inline-block;
    }
    ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 0.6rem; }
    li { padding: 0.8rem 1rem; display: flex; justify-content: space-between; gap: 1rem; align-items: center; }
    li a { font-weight: 600; text-decoration: none; }
    li a:hover { text-decoration: underline; }
    .meta { color: #78716c; font-size: 0.9rem; }
    .empty { color: #78716c; margin: 0; }
    .error { background: #fef2f2; color: #991b1b; padding: 0.6rem 0.8rem; border-radius: 6px; }
    article { padding: 1.25rem; }
    article h1 { margin-bottom: 0.35rem; }
    .notes { white-space: pre-wrap; }
    .actions { display: flex; gap: 0.75rem; align-items: center; margin-top: 1.25rem; }
    nav { margin-bottom: 1rem; }
  </style>
</head>
<body>
  <main>
    ${body}
  </main>
</body>
</html>`;
}

function bookItem(book) {
  const action =
    book.status === "reading"
      ? `<form method="post" action="/books/${book.id}/finish"><button type="submit">Mark finished</button></form>`
      : "";
  return `<li>
    <div>
      <a href="/books/${book.id}">${escapeHtml(book.title)}</a>
      <div class="meta">${escapeHtml(book.author)}</div>
    </div>
    ${action}
  </li>`;
}

function bookList(books, emptyText) {
  if (!books.length) return `<p class="empty">${emptyText}</p>`;
  return `<ul>${books.map(bookItem).join("")}</ul>`;
}

export function homePage(books, { error } = {}) {
  const reading = books.filter((book) => book.status === "reading");
  const finished = books.filter((book) => book.status === "finished");
  const errorHtml = error ? `<p class="error">${escapeHtml(error)}</p>` : "";
  return layout(
    "Books",
    `<h1>Books</h1>
    <p class="lede">What you're reading, and what you've finished.</p>
    ${errorHtml}
    <form method="post" action="/books">
      <label>Title <input name="title" required maxlength="200"></label>
      <label>Author <input name="author" required maxlength="200"></label>
      <label>Notes <textarea name="notes" maxlength="5000"></textarea></label>
      <div><button type="submit">Add book</button></div>
    </form>
    <h2>Currently reading</h2>
    ${bookList(reading, "Nothing in progress.")}
    <h2>Finished</h2>
    ${bookList(finished, "No finished books yet.")}`
  );
}

export function bookPage(book) {
  const finished =
    book.status === "finished"
      ? `<p class="meta">Finished</p>`
      : `<form method="post" action="/books/${book.id}/finish"><button type="submit">Mark finished</button></form>`;
  const notes = book.notes
    ? `<p class="notes">${escapeHtml(book.notes)}</p>`
    : `<p class="empty">No notes.</p>`;
  return layout(
    book.title,
    `<nav><a href="/">All books</a></nav>
    <article>
      <h1>${escapeHtml(book.title)}</h1>
      <p class="meta">${escapeHtml(book.author)}</p>
      ${notes}
      <div class="actions">${finished}</div>
    </article>`
  );
}

export function notFoundPage() {
  return layout(
    "Not found",
    `<h1>Not found</h1><p><a href="/">Back to books</a></p>`
  );
}

