import { createServer } from "node:http";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { createStore } from "./lib/store.js";
import { bookPage, homePage, notFoundPage } from "./lib/html.js";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PORT = Number(process.env.PORT) || 3000;
const DATA_FILE =
  process.env.DATA_FILE || path.join(__dirname, "data", "books.json");

const store = createStore(DATA_FILE);

function send(res, status, html) {
  res.writeHead(status, {
    "content-type": "text/html; charset=utf-8",
    "cache-control": "no-store",
  });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { location });
  res.end();
}

async function readBody(req) {
  const chunks = [];
  for await (const chunk of req) chunks.push(chunk);
  return new URLSearchParams(Buffer.concat(chunks).toString("utf8"));
}

export function createApp(bookStore) {
  return async function handle(req, res) {
    const url = new URL(req.url || "/", `http://${req.headers.host || "localhost"}`);
    const pathname = url.pathname;
    const method = req.method || "GET";

    try {
      if (method === "GET" && pathname === "/") {
        send(res, 200, homePage(await bookStore.list()));
        return;
      }

      if (method === "POST" && pathname === "/books") {
        const body = await readBody(req);
        const title = body.get("title") ?? "";
        const author = body.get("author") ?? "";
        if (!title.trim() || !author.trim()) {
          send(
            res,
