import { describe, expect, it } from "vitest";
import { bookPage, escapeHtml, homePage } from "./html.js";

const reading = {
  id: "abc",
  title: "Piranesi",
  author: "Susanna Clarke",
  notes: "Halls & statues",
  status: "reading",
};

const finished = {
  id: "def",
  title: "Circe",
  author: "Madeline Miller",
  notes: "",
  status: "finished",
};

describe("pages", () => {
  it("escapes html", () => {
    expect(escapeHtml(`<a href="x">'`)).toBe("&lt;a href=&quot;x&quot;&gt;&#39;");
  });

  it("lists reading and finished books separately", () => {
    const html = homePage([reading, finished]);
    expect(html).toContain("Currently reading");
    expect(html).toContain("Finished");
    expect(html).toContain('href="/books/abc"');
    expect(html).toContain("Piranesi");
    expect(html).toContain('action="/books/abc/finish"');
    expect(html).not.toContain('action="/books/def/finish"');
    const readingIdx = html.indexOf("Currently reading");
    const finishedIdx = html.indexOf(">Finished<");
    expect(html.indexOf("Piranesi")).toBeGreaterThan(readingIdx);
    expect(html.indexOf("Piranesi")).toBeLessThan(finishedIdx);
    expect(html.indexOf("Circe")).toBeGreaterThan(finishedIdx);
  });

  it("shows title, author, and notes on the book page", () => {
    const html = bookPage(reading);
    expect(html).toContain("Piranesi");
    expect(html).toContain("Susanna Clarke");
    expect(html).toContain("Halls &amp; statues");
  });
});

