import { mkdtemp, rm } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { createStore } from "./store.js";

let dir;

afterEach(async () => {
  if (dir) await rm(dir, { recursive: true, force: true });
});

async function tempStore() {
  dir = await mkdtemp(path.join(os.tmpdir(), "books-"));
  return createStore(path.join(dir, "books.json"));
}

describe("store", () => {
  it("adds a book and keeps it after a new store opens the same file", async () => {
    const file = path.join(await mkdtemp(path.join(os.tmpdir(), "books-")), "books.json");
    dir = path.dirname(file);
    const store = createStore(file);
    const book = await store.add({
      title: "The Left Hand of Darkness",
      author: "Ursula K. Le Guin",
      notes: "Winter",
    });

    expect(book.status).toBe("reading");
    const reopened = createStore(file);
    const saved = await reopened.get(book.id);
    expect(saved).toMatchObject({
      title: "The Left Hand of Darkness",
      author: "Ursula K. Le Guin",
      notes: "Winter",
      status: "reading",
    });
  });

  it("marks a book finished", async () => {
    const store = await tempStore();
    const book = await store.add({ title: "Kindred", author: "Octavia Butler" });
    const finished = await store.finish(book.id);
    expect(finished.status).toBe("finished");
    expect(finished.finishedAt).toBeTruthy();
    expect(await store.finish("missing")).toBeNull();
  });
});

